import { test, expect } from '@playwright/test';

test.describe('Video Player Responsive Resize on Tablet Viewports', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/video-player');
  });

  test('should resize video player proportionally when viewport width is reduced to tablet size', async ({ page }) => {
    // Set viewport to tablet size (768px width)
    await page.setViewportSize({ width: 720, height: 1020 });

    // Verify video player is visible
    const videoContainer = page.getByRole('region', { name: /video player/i });
    await expect(videoContainer).toBeVisible();

    // Verify video element exists and has correct aspect ratio class
    const videoElement = page.getByRole('video');
    await expect(videoElement).toBeVisible();
    await expect(videoElement).toHaveClass(/aspect-ratio-16-9/);

    // Verify video container has correct responsive class
    const responsiveClass = page.getByRole('region', { name: /video player/i }).first().getAttribute('class');
    expect(responsiveClass).toContain('responsive-video');

    // Verify video width is set to 100% of container
    const videoWidth = await videoElement.evaluate((el) => el.style.width);
    expect(videoWidth).toBe('100%');

    // Verify video height is calculated proportionally
    const videoHeight = await videoElement.evaluate((el) => el.style.height);
    expect(videoHeight).toBe('auto');
  });

  test('should maintain proportional aspect ratio when viewport is resized from desktop to tablet', async ({ page }) => {
    // Set viewport to desktop size (1920px width)
    await page.setViewportSize({ width: 1920, height: 1080 });

    // Verify video player is visible and has correct aspect ratio
    const videoContainer = page.getByRole('region', { name: /video player/i });
    await expect(videoContainer).toBeVisible();

    const videoElement = page.getByRole('video');
    await expect(videoElement).toBeVisible();
    await expect(videoElement).toHaveClass(/aspect-ratio-16-9/);

    // Verify video width is 100%
    const videoWidth = await videoElement.evaluate((el) => el.style.width);
    expect(videoWidth).toBe('100%');

    // Verify video height is calculated proportionally
    const videoHeight = await videoElement.evaluate((el) => el.style.height);
    expect(videoHeight).toBe('auto');

    // Resize viewport to tablet size (768px width)
    await page.setViewportSize({ width: 720, height: 1000 });

    // Verify video element still exists and has correct aspect ratio
    await expect(videoElement).toBeVisible();
    await expect(videoElement).toHaveClass(/aspect-ratio-16-9/);

    // Verify video width is still 100% of the new container width
    const newVideoWidth = await videoElement.evaluate((el) => el.style.width);
    expect(newVideoWidth).toBe('100%');

    // Verify video height is still calculated proportionally
    const newVideoHeight = await videoElement.evaluate((el) => el.style.height);
    expect(newVideoHeight).toBe('auto');
  });
});
